for rel, old, new in EDITS:
    s = rd(rel) if (root / rel).exists() else ""
    if old == "CREATE":
        assert not (root / rel).exists(); wr(rel, new)
        continue
    if old == "APPEND":
        wr(rel, s + ("" if s.endswith("\n") else "\n") + new)
